{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _user(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": user["name"],
            "owes": dict(user["owes"]),
            "owed_by": dict(user["owed_by"]),
            "balance": balance,
        }

    def _users(self, names):
        return {"users": [self._user(n) for n in sorted(names)]}

    def get(self, url, payload=None):
        if url == "/users":
            data = json.loads(payload) if payload else {}
            names = data.get("users")
            if names is None:
                names = self.users.keys()
            return json.dumps(self._users(n for n in names if n in self.users))
        raise ValueError(f"Unknown URL: {url}")

    def post(self, url, payload=None):
        data = json.loads(payload) if payload else {}
        if url == "/add":
            name = data["user"]
            if name not in self.users:
                self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._user(name))
        if url == "/iou":
            lender_name, borrower_name = data["lender"], data["borrower"]
            amount = data["amount"]
            lender = self.users[lender_name]
            borrower = self.users[borrower_name]
            # Net amount the borrower owes the lender after this IOU.
            net = (
                lender["owed_by"].pop(borrower_name, 0)
                - lender["owes"].pop(borrower_name, 0)
                + amount
            )
            borrower["owes"].pop(lender_name, None)
            borrower["owed_by"].pop(lender_name, None)
            if net > 0:
                lender["owed_by"][borrower_name] = net
                borrower["owes"][lender_name] = net
            elif net < 0:
                lender["owes"][borrower_name] = -net
                borrower["owed_by"][lender_name] = -net
            return json.dumps(self._users([lender_name, borrower_name]))
        raise ValueError(f"Unknown URL: {url}")
"}
